package aidr

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
	"time"
)

// Cross-language conformance. Replays sdk/testdata/vectors.json, generated by the Python
// implementation, exactly as the Node suite does. Three SDKs verifying the same credentials is
// only useful if they agree, and agreement asserted in a README is not agreement.
//
// The vectors are real and were produced by a working implementation, so a failure here indicates
// a bug in this Go code rather than in the vectors. Run with `go test ./...` (golang:1.23 works;
// see sdk/go/README or run it in a container where no local toolchain exists).

type vectorCase struct {
	Name             string            `json:"name"`
	Method           string            `json:"method"`
	URL              string            `json:"url"`
	Headers          map[string]string `json:"headers"`
	Expect           string            `json:"expect"`
	ExpectCode       string            `json:"expect_code"`
	ExpectedAudience string            `json:"expected_audience"`
	MinAssurance     int               `json:"min_assurance"`
	EvaluateAt       int64             `json:"evaluate_at"`
}

type sequenceStep struct {
	Case       string `json:"case"`
	Expect     string `json:"expect"`
	ExpectCode string `json:"expect_code"`
}

type vectorSequence struct {
	Name  string         `json:"name"`
	Steps []sequenceStep `json:"steps"`
}

type vectorSuite struct {
	Algorithm            string          `json:"algorithm"`
	Issuer               string          `json:"issuer"`
	JWKS                 json.RawMessage `json:"jwks"`
	AID                  string          `json:"aid"`
	Organization         string          `json:"organization"`
	ExpectedAssurance    int             `json:"expected_assurance"`
	ExpectedAgAL         int             `json:"expected_agal"`
	ExpectedOAL          int             `json:"expected_oal"`
	ExpectedKAL          int             `json:"expected_kal"`
	ExpectedCapabilities []string        `json:"expected_capabilities"`
	Revocation           struct {
		DeltaBefore  string `json:"delta_before_revocation"`
		DeltaWithGap string `json:"delta_with_gap"`
		DeltaAfter   string `json:"delta_after_revocation"`
		FilterAfter  string `json:"filter_after_revocation"`
		FilterAbsent string `json:"filter_absent_probe"`
	} `json:"revocation"`
	Cases     []vectorCase     `json:"cases"`
	Sequences []vectorSequence `json:"sequences"`
	// FreshnessCases are verified at their own EvaluateAt, against trust loaded at the
	// document's: they pin MaxRevocationAgeDefault.
	FreshnessCases          []vectorCase `json:"freshness_cases"`
	MaxRevocationAgeSeconds int64        `json:"max_revocation_age_seconds"`
}

type vectorDocument struct {
	// EvaluateAt pins the instant every case is evaluated at. The artefacts are real and
	// time-bound — signatures expire after 300s — so wall-clock evaluation would make this suite
	// pass only in the minutes after the vectors were generated.
	EvaluateAt int64         `json:"evaluate_at"`
	Suites     []vectorSuite `json:"suites"`
}

// evaluateAt is set by loadVectors from the pinned instant in the vectors.
var evaluateAt time.Time

func loadVectors(t *testing.T) vectorDocument {
	t.Helper()
	// AIDR_VECTORS: replay another signer's vectors (the conformance gate, docs/13).
	path := os.Getenv("AIDR_VECTORS")
	if path == "" {
		path = filepath.Join("..", "..", "testdata", "vectors.json")
		// In the public repository the module sits at go/, beside sdk/ (scripts/mirror_sdk.py).
		if _, err := os.Stat(path); err != nil {
			path = filepath.Join("..", "..", "sdk", "testdata", "vectors.json")
		}
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Skipf("test vectors not found at %s — run scripts/generate_test_vectors.py", path)
	}
	var document vectorDocument
	if err := json.Unmarshal(data, &document); err != nil {
		t.Fatalf("vectors are not valid JSON: %v", err)
	}
	evaluateAt = time.Unix(document.EvaluateAt, 0).UTC()
	return document
}

func trustFor(t *testing.T, suite vectorSuite, deltaToken string) *TrustStore {
	t.Helper()
	trust, err := BuildTrustStore(suite.JWKS, TrustOptions{
		DeltaToken: deltaToken, ExpectedIssuer: suite.Issuer,
	})
	if err != nil {
		t.Fatalf("could not build trust store: %v", err)
	}
	return trust
}

func TestCrossLanguageConformance(t *testing.T) {
	document := loadVectors(t)

	for _, suite := range document.Suites {
		suite := suite
		t.Run(suite.Algorithm, func(t *testing.T) {
			if time.Duration(suite.MaxRevocationAgeSeconds)*time.Second != MaxRevocationAgeDefault {
				t.Fatalf("vectors pin a %d s revocation age, the SDK %v",
					suite.MaxRevocationAgeSeconds, MaxRevocationAgeDefault)
			}
			for _, testCase := range append(append([]vectorCase{}, suite.Cases...), suite.FreshnessCases...) {
				testCase := testCase
				t.Run(testCase.Name, func(t *testing.T) {
					trust := trustFor(t, suite, suite.Revocation.DeltaBefore)
					verifier := NewVerifier(trust, Policy{
						ExpectedIssuer:   suite.Issuer,
						ExpectedAudience: testCase.ExpectedAudience,
						MinAssurance:     testCase.MinAssurance,
						RequireNonce:     true,
					}, NewNonceCache(0, 0))

					at := evaluateAt
					if testCase.EvaluateAt != 0 {
						at = time.Unix(testCase.EvaluateAt, 0).UTC()
					}
					result, err := verifier.Verify(
						testCase.Method, testCase.URL, testCase.Headers, at)

					if testCase.Expect == "allow" {
						if err != nil {
							t.Fatalf("expected allow, got %v", err)
						}
						if result.AID != suite.AID {
							t.Errorf("aid = %q, want %q", result.AID, suite.AID)
						}
						if result.Assurance != suite.ExpectedAssurance {
							t.Errorf("assurance = %d, want %d",
								result.Assurance, suite.ExpectedAssurance)
						}
						if result.AgAL != suite.ExpectedAgAL || result.OAL != suite.ExpectedOAL ||
							result.KAL != suite.ExpectedKAL {
							t.Errorf("axes = AgAL%d OAL%d KAL%d, want AgAL%d OAL%d KAL%d",
								result.AgAL, result.OAL, result.KAL,
								suite.ExpectedAgAL, suite.ExpectedOAL, suite.ExpectedKAL)
						}
						return
					}

					if err == nil {
						t.Fatal("expected a denial, got an acceptance")
					}
					if testCase.ExpectCode != "" && Code(err) != testCase.ExpectCode {
						t.Errorf("code = %q, want %q (%v)", Code(err), testCase.ExpectCode, err)
					}
				})
			}
		})
	}
}

func TestRevokedAgentIsRefusedAfterRefresh(t *testing.T) {
	for _, suite := range loadVectors(t).Suites {
		trust := trustFor(t, suite, suite.Revocation.DeltaAfter)
		verifier := NewVerifier(trust, Policy{ExpectedIssuer: suite.Issuer},
			NewNonceCache(0, 0))

		allowCase := firstAllowCase(suite)
		_, err := verifier.Verify(allowCase.Method, allowCase.URL, allowCase.Headers, evaluateAt)
		if Code(err) != CodeAgentRevoked {
			t.Errorf("%s: code = %q, want %q", suite.Algorithm, Code(err), CodeAgentRevoked)
		}
	}
}

func TestBloomFilterMatchesTheOtherSDKs(t *testing.T) {
	// The hash construction must match Python and Node exactly, or a revoked agent silently
	// verifies in one language and not another.
	for _, suite := range loadVectors(t).Suites {
		trust := trustFor(t, suite, "")
		if _, err := trust.IngestFilter(suite.Revocation.FilterAfter); err != nil {
			t.Fatalf("%s: could not ingest filter: %v", suite.Algorithm, err)
		}
		if !trust.Revocation.filter.Has(suite.AID) {
			t.Errorf("%s: revoked identifier missing from the published filter", suite.Algorithm)
		}
		// An identifier the generator confirmed this filter rules out (a bloom filter has false positives).
		absent := suite.Revocation.FilterAbsent
		if absent == "" {
			absent = "aid:v1:acme-corp:NEVER-ISSUED:0000"
		}
		if trust.Revocation.filter.Has(absent) {
			t.Errorf("%s: filter reported an identifier that was never revoked", suite.Algorithm)
		}
	}
}

func TestFailsClosedWithoutRevocationState(t *testing.T) {
	// A site that never loaded revocation state is not verifying; it must not pretend to.
	for _, suite := range loadVectors(t).Suites {
		trust := trustFor(t, suite, "")
		verifier := NewVerifier(trust, Policy{ExpectedIssuer: suite.Issuer}, NewNonceCache(0, 0))

		allowCase := firstAllowCase(suite)
		_, err := verifier.Verify(allowCase.Method, allowCase.URL, allowCase.Headers, evaluateAt)
		if !IsUnavailable(err) {
			t.Errorf("%s: expected a fail-closed refusal, got %v", suite.Algorithm, err)
		}
	}
}

func TestSoftFailMustBeChosen(t *testing.T) {
	for _, suite := range loadVectors(t).Suites {
		trust := trustFor(t, suite, "")
		verifier := NewVerifier(trust, Policy{
			ExpectedIssuer: suite.Issuer, AllowUnknownRevocation: true,
		}, NewNonceCache(0, 0))

		allowCase := firstAllowCase(suite)
		result, err := verifier.Verify(allowCase.Method, allowCase.URL, allowCase.Headers, evaluateAt)
		if err != nil {
			t.Fatalf("%s: soft-fail should permit: %v", suite.Algorithm, err)
		}
		if len(result.Warnings) == 0 {
			t.Errorf("%s: soft-fail must warn", suite.Algorithm)
		}
	}
}

func TestDeltaWithAGapIsRefused(t *testing.T) {
	// Applying a delta that begins past the local serial would silently lose every revocation in
	// between.
	for _, suite := range loadVectors(t).Suites {
		trust := trustFor(t, suite, "")
		if _, err := trust.IngestDelta(suite.Revocation.DeltaWithGap); !IsUnavailable(err) {
			t.Errorf("%s: expected a gap refusal, got %v", suite.Algorithm, err)
		}
	}
}

func TestReplayIsRefused(t *testing.T) {
	for _, suite := range loadVectors(t).Suites {
		trust := trustFor(t, suite, suite.Revocation.DeltaBefore)
		verifier := NewVerifier(trust, Policy{
			ExpectedIssuer: suite.Issuer, RequireNonce: true,
		}, NewNonceCache(0, 0))

		allowCase := firstAllowCase(suite)
		if _, err := verifier.Verify(allowCase.Method, allowCase.URL, allowCase.Headers, evaluateAt); err != nil {
			t.Fatalf("%s: first request should verify: %v", suite.Algorithm, err)
		}
		_, err := verifier.Verify(allowCase.Method, allowCase.URL, allowCase.Headers, evaluateAt)
		if Code(err) != CodeReplayDetected {
			t.Errorf("%s: replay not detected, got %v", suite.Algorithm, err)
		}
	}
}

// Multi-step vectors: each sequence runs in order against one verifier and one replay cache.
func TestCrossLanguageSequences(t *testing.T) {
	for _, suite := range loadVectors(t).Suites {
		suite := suite
		cases := map[string]vectorCase{}
		for _, c := range suite.Cases {
			cases[c.Name] = c
		}
		for _, sequence := range suite.Sequences {
			sequence := sequence
			t.Run(suite.Algorithm+"/"+sequence.Name, func(t *testing.T) {
				trust := trustFor(t, suite, suite.Revocation.DeltaBefore)
				verifier := NewVerifier(trust, Policy{ExpectedIssuer: suite.Issuer, RequireNonce: true},
					NewNonceCache(0, 0))
				for _, step := range sequence.Steps {
					c := cases[step.Case]
					_, err := verifier.Verify(c.Method, c.URL, c.Headers, evaluateAt)
					if step.Expect == "allow" {
						if err != nil {
							t.Fatalf("%s: expected allow, got %v", step.Case, err)
						}
						continue
					}
					if err == nil {
						t.Fatalf("%s: expected a denial", step.Case)
					}
					if step.ExpectCode != "" && Code(err) != step.ExpectCode {
						t.Errorf("%s: code = %q, want %q", step.Case, Code(err), step.ExpectCode)
					}
				}
			})
		}
	}
}

func TestNonceCacheRefusesWhenFullRatherThanForgetting(t *testing.T) {
	cache := NewNonceCache(600*time.Second, 2)
	for _, nonce := range []string{"a", "b"} {
		if seen, err := cache.Check(nonce); seen || err != nil {
			t.Fatalf("first use of %q: seen=%v err=%v", nonce, seen, err)
		}
	}
	if _, err := cache.Check("c"); !IsUnavailable(err) {
		t.Fatalf("expected an unavailable error from a full cache, got %v", err)
	}
	if seen, _ := cache.Check("a"); !seen {
		t.Fatal("a live nonce was forgotten")
	}
}

func TestNonceCacheMakesRoomFromExpiredEntries(t *testing.T) {
	cache := NewNonceCache(-time.Second, 2)
	for _, nonce := range []string{"a", "b", "c", "d"} {
		if _, err := cache.Check(nonce); err != nil {
			t.Fatalf("expired entries should make room: %v", err)
		}
	}
}

func firstAllowCase(suite vectorSuite) vectorCase {
	for _, testCase := range suite.Cases {
		if testCase.Expect == "allow" && testCase.ExpectedAudience == "" {
			return testCase
		}
	}
	panic("no unconditional allow case in the vectors")
}
